@sealed
class ArchiveImpl extends RustOpaque implements Archive {
  // Not to be used by end users
  ArchiveImpl.frbInternalDcoDecode(List<dynamic> wire) : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  ArchiveImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount: RustLib.instance.api.rust_arc_increment_strong_count_Archive,
    rustArcDecrementStrongCount: RustLib.instance.api.rust_arc_decrement_strong_count_Archive,
    rustArcDecrementStrongCountPtr: RustLib.instance.api.rust_arc_decrement_strong_count_ArchivePtr,
  );

  /// Adds files by their paths; returns how many were new.
  Future<int> addFiles({required String space, required List<String> paths}) =>
      RustLib.instance.api.crateApiArchiveArchiveAddFiles(that: this, space: space, paths: paths);

  /// Adds a label.
  Future<void> addLabel({required String space, required String document, required String label}) =>
      RustLib.instance.api.crateApiArchiveArchiveAddLabel(that: this, space: space, document: document, label: label);

  /// The name people read for this device, if it was given one.
  Future<String?> deviceName() => RustLib.instance.api.crateApiArchiveArchiveDeviceName(that: this);

  /// A document with its versions, fields and text.
  Future<DocumentDetail> document({required String space, required String document}) =>
      RustLib.instance.api.crateApiArchiveArchiveDocument(that: this, space: space, document: document);

  /// The documents found by `words` (all, without words) in a space, or in the bin of it – the newest first.
  Future<List<DocumentItem>> documents({required String space, required String words, required bool bin}) =>
      RustLib.instance.api.crateApiArchiveArchiveDocuments(that: this, space: space, words: words, bin: bin);

  /// Founds a space; returns its identity.
  Future<String> foundSpace({required String name}) =>
      RustLib.instance.api.crateApiArchiveArchiveFoundSpace(that: this, name: name);

  /// An invitation for another device – the person's own or someone else's – with `rights` (`read`, `write`,
  /// `manage`), good for a day.
  Future<String> invite({required String space, required String rights}) =>
      RustLib.instance.api.crateApiArchiveArchiveInvite(that: this, space: space, rights: rights);

  /// Asks to join a space with an invitation; its documents arrive once a device that may manage it added this one.
  /// Returns the space's identity.
  Future<String> join({required String invitation, String? name}) =>
      RustLib.instance.api.crateApiArchiveArchiveJoin(that: this, invitation: invitation, name: name);

  /// The key of the data folder, for Dart to keep.
  String key() => RustLib.instance.api.crateApiArchiveArchiveKey(that: this);

  /// The members of a synchronised space, as its relay lists them.
  Future<List<MemberItem>> members({required String space}) =>
      RustLib.instance.api.crateApiArchiveArchiveMembers(that: this, space: space);

  /// The bytes of a version (from 1), to show or share.
  Future<Uint8List> original({required String space, required String document, required int number}) =>
      RustLib.instance.api.crateApiArchiveArchiveOriginal(that: this, space: space, document: document, number: number);

  /// Brings a space back with its recovery code, when no device of it is left.
  Future<SyncItem> recover({required String relay, required String space, required String code, String? name}) =>
      RustLib.instance.api.crateApiArchiveArchiveRecover(
        that: this,
        relay: relay,
        space: space,
        code: code,
        name: name,
      );

  /// Takes a label off.
  Future<void> removeLabel({required String space, required String document, required String label}) => RustLib
      .instance
      .api
      .crateApiArchiveArchiveRemoveLabel(that: this, space: space, document: document, label: label);

  /// Removes a member by its identity; it gets nothing written after. Returns its name.
  Future<String> removeMember({required String space, required String member}) =>
      RustLib.instance.api.crateApiArchiveArchiveRemoveMember(that: this, space: space, member: member);

  /// Gives this device a name people read – the other members of a space see it.
  Future<void> setDeviceName({required String name}) =>
      RustLib.instance.api.crateApiArchiveArchiveSetDeviceName(that: this, name: name);

  /// Gives a document a new title.
  Future<void> setTitle({required String space, required String document, required String title}) =>
      RustLib.instance.api.crateApiArchiveArchiveSetTitle(that: this, space: space, document: document, title: title);

  /// Puts a document into the bin, or takes it out.
  Future<void> setTrashed({required String space, required String document, required bool trashed}) => RustLib
      .instance
      .api
      .crateApiArchiveArchiveSetTrashed(that: this, space: space, document: document, trashed: trashed);

  /// The spaces, in the order they were founded or joined.
  Future<List<SpaceItem>> spaces() => RustLib.instance.api.crateApiArchiveArchiveSpaces(that: this);

  /// Starts synchronising a space through a relay (`http://…`), as this device with `name` (or its own). Returns the
